int vfprintf(FILE*প্রবাহ_মান,const char*ফাইল_ভুক্তি,va_list 첫째값){char 둘째값[2048];int 개수=vsnprintf(둘째값,sizeof(둘째값),ফাইল_ভুক্তি,첫째값);if(개수>2047)개수=2047;return fwrite(둘째값,1,개수,প্রবাহ_মান)==(size_t)개수?개수:-1;}
